<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$db=saas_db();
$adminMode=false;$ticketId=(int)($_GET['ticket_id']??0);$slug=trim((string)($_GET['slug']??''));$token=trim((string)($_GET['token']??''));
if($ticketId>0){
    saas_require_login();$tourId=saas_require_tour();saas_require_permission('passenger.create');$adminMode=true;
    $q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.full_name,pp.phone,t.id tour_id,t.name tour_name,t.slug,t.start_date,t.end_date,o.name organization_name,o.currency,ti.id ticket_id,ti.ticket_number,ti.status ticket_status,ti.template_key,ti.qr_token_hash,ti.issued_at FROM ticket_instances ti JOIN tour_passengers tp ON tp.id=ti.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id WHERE ti.id=? AND ti.tour_id=? AND t.organization_id=? AND ti.status='ISSUED' LIMIT 1");$q->execute([$ticketId,$tourId,saas_current_organization_id()]);$ticket=$q->fetch();if(!$ticket){http_response_code(404);exit('Issued ticket not found.');}
}else{
    if($slug===''||!preg_match('/^[a-f0-9]{64}$/',$token)){http_response_code(404);exit('Ticket link is invalid.');}
    $hash=hash('sha256',$token);
    $q=$db->prepare("SELECT tp.id tp_id,tp.status,tp.fee,tp.discount,pp.full_name,pp.phone,t.id tour_id,t.name tour_name,t.slug,t.start_date,t.end_date,o.name organization_name,o.currency,ti.id ticket_id,ti.ticket_number,ti.status ticket_status,ti.template_key,ti.qr_token_hash,ti.issued_at FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN organizations o ON o.id=t.organization_id JOIN ticket_instances ti ON ti.tour_passenger_id=tp.id AND ti.status='ISSUED' WHERE t.slug=? AND tp.booking_access_token_hash=? AND tp.booking_access_token_revoked_at IS NULL AND tp.status='ACTIVE' AND o.status='ACTIVE' ORDER BY ti.id DESC LIMIT 1");$q->execute([$slug,$hash]);$ticket=$q->fetch();if(!$ticket){http_response_code(404);exit('Active ticket not found.');}
}
$q=$db->prepare("SELECT b.name bus_name,b.bus_number,s.seat_code FROM passenger_seat_assignments psa JOIN buses b ON b.id=psa.bus_id JOIN seats s ON s.id=psa.seat_id WHERE psa.tour_passenger_id=? LIMIT 1");$q->execute([(int)$ticket['tp_id']]);$seat=$q->fetch();
$q=$db->prepare("SELECT r.room_no,r.room_type FROM room_assignments ra JOIN rooms r ON r.id=ra.room_id WHERE ra.tour_passenger_id=? LIMIT 1");$q->execute([(int)$ticket['tp_id']]);$room=$q->fetch();
$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_id=? AND tour_passenger_id=?');$q->execute([(int)$ticket['tour_id'],(int)$ticket['tp_id']]);$paid=(float)$q->fetchColumn();$total=max(0,(float)$ticket['fee']-(float)$ticket['discount']);$due=max(0,$total-$paid);$currency=$ticket['currency']?:'BDT';
$templates=['classic'=>'Classic','travel'=>'Travel','event'=>'Event'];$template=strtolower(trim((string)($_GET['template']??$ticket['template_key']??'classic')));if(!isset($templates[$template]))$template='classic';$requestedLayout=(string)($_GET['layout']??'1up');$printLayout=in_array($requestedLayout,['1up','2up','3up'],true)?$requestedLayout:'1up';$saveError='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['template'])){try{saas_check_csrf();$new=strtolower(trim((string)$_POST['template']));if(!isset($templates[$new]))throw new RuntimeException('Invalid ticket design.');$q=$db->prepare("UPDATE ticket_instances SET template_key=?,updated_at=NOW() WHERE id=? AND tour_passenger_id=? AND status='ISSUED'");$q->execute([$new,(int)$ticket['ticket_id'],(int)$ticket['tp_id']]);$template=$new;saas_audit('ticket.template_changed','ticket_instance',(int)$ticket['ticket_id'],json_encode(['template'=>$new],JSON_UNESCAPED_UNICODE));}catch(Throwable $e){$saveError='Could not save the ticket design.';}}
$designQ=$db->prepare('SELECT background_image,elements_json FROM tour_ticket_designs WHERE tour_id=? AND organization_id=? LIMIT 1');$designQ->execute([(int)$ticket['tour_id'],saas_current_organization_id()]);$customDesign=$designQ->fetch();$customElements=$customDesign?json_decode((string)$customDesign['elements_json'],true):null;if(!is_array($customElements))$customElements=null;
$qrToken=hash_hmac('sha256',(string)$ticket['ticket_number'],saas_app_key());$qrHash=hash('sha256',$qrToken);if(!hash_equals((string)$ticket['qr_token_hash'],$qrHash)){http_response_code(409);exit('Ticket QR is not synchronized. Please reissue the ticket.');}
$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'');$verifyUrl=$scheme.'://'.$host.'/ticket_verify.php?ticket='.rawurlencode($ticket['ticket_number']).'&q='.rawurlencode($qrToken);$qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=300x300&margin=4&data='.rawurlencode($verifyUrl);$accent=$template==='travel'?'#0b7a75':($template==='event'?'#7c3aed':'#155eef');
$ticketData=['organization'=>$ticket['organization_name'],'tour'=>$ticket['tour_name'],'dates'=>trim((string)$ticket['start_date']).($ticket['end_date']?' — '.(string)$ticket['end_date']:''),'guest'=>$ticket['full_name'],'phone'=>$ticket['phone'],'bus'=>$seat['bus_name']??'Not assigned','bus_number'=>$seat['bus_number']??'—','seat'=>$seat['seat_code']??'Not assigned','room'=>$room?trim((string)$room['room_no'].' · '.(string)$room['room_type']):'Not assigned','paid'=>number_format($paid,2),'due'=>$due<=0?'PAID':$currency.' '.number_format($due,2),'ticket'=>$ticket['ticket_number'],'currency'=>$currency];
function ticket_card(array $d,string $template,string $qrUrl,string $accent,?array $custom=null,?string $background=null): void {
 if($custom){
  ?><article class="ticket custom-ticket"><div class="artwork" style="background-image:url('<?=saas_h((string)$background)?>')"></div><div class="ticket-overlay"><?php
  foreach($custom as $key=>$v){if($key==='qr'){?><div class="custom-el qr-custom" style="left:<?=((int)$v['x'])?>px;top:<?=((int)$v['y'])?>px;width:<?=((int)$v['w'])?>px;height:<?=((int)$v['h'])?>px"><img src="<?=saas_h($qrUrl)?>" alt="QR"></div><?php continue;}if(!array_key_exists($key,$d))continue;?><div class="custom-el" style="left:<?=((int)$v['x'])?>px;top:<?=((int)$v['y'])?>px;width:<?=((int)$v['w'])?>px;height:<?=((int)$v['h'])?>px;font-size:<?=((int)$v['size'])?>px;font-weight:<?=((int)$v['weight'])?>"><?=saas_h((string)$d[$key])?></div><?php }
  ?></div></article><?php return;
 }
 ?><article class="ticket ticket-<?=saas_h($template)?>"><div class="artwork"></div><div class="ticket-overlay"><div class="ticket-title"><div class="org"><?=saas_h($d['organization'])?></div><h1><?=saas_h($d['tour'])?></h1><div class="dates"><?=saas_h($d['dates'])?></div></div><div class="guest-block"><div class="label">GUEST NAME</div><div class="guest"><?=saas_h($d['guest'])?></div><div class="phone"><?=saas_h($d['phone'])?></div></div><div class="info-grid"><div><span>BUS</span><strong><?=saas_h($d['bus'])?></strong></div><div><span>BUS NO.</span><strong><?=saas_h($d['bus_number'])?></strong></div><div><span>SEAT</span><strong><?=saas_h($d['seat'])?></strong></div><div><span>ROOM</span><strong><?=saas_h($d['room'])?></strong></div><div><span>PAID</span><strong><?=saas_h($d['currency'])?> <?=saas_h($d['paid'])?></strong></div><div><span>DUE</span><strong class="due"><?=saas_h($d['due'])?></strong></div></div><div class="ticket-no">TICKET <?=saas_h($d['ticket'])?></div><div class="qr-frame"><img src="<?=saas_h($qrUrl)?>" alt="Ticket QR"></div></div></article><?php
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket <?=saas_h($ticket['ticket_number'])?></title><style>
@page one-up{size:A4 landscape;margin:0}@page two-up{size:A4 portrait;margin:0}@page three-up{size:A4 portrait;margin:0}*{box-sizing:border-box}html,body{margin:0;padding:0;font-family:Arial,sans-serif;color:#182230;background:#eef2f6}.controls{max-width:1050px;margin:16px auto;padding:12px 16px;background:#fff;border:1px solid #d0d5dd;border-radius:12px;display:flex;gap:10px;align-items:center;justify-content:center;flex-wrap:wrap}.controls select,.controls button{padding:9px 12px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.controls button{cursor:pointer;font-weight:700}.controls .primary{background:<?=saas_h($accent)?>;color:#fff;border-color:<?=saas_h($accent)?>}.controls a{text-decoration:none}.ok{width:100%;text-align:center;color:#067647}.sheet{width:297mm;margin:20px auto;page:one-up}.ticket{width:297mm;height:118.8mm;position:relative;overflow:hidden;background:#fff;page-break-inside:avoid}.artwork{position:absolute;inset:0;background-image:url('assets/ticket-template1.jpg');background-size:100% 100%;background-repeat:no-repeat}.custom-ticket .artwork{background-size:100% 100%;background-repeat:no-repeat}.custom-el{position:absolute;overflow:hidden;white-space:nowrap;line-height:1.1;display:flex;align-items:center;padding:2px 4px}.qr-custom{padding:0;background:#fff}.qr-custom img{width:100%;height:100%;display:block}.ticket-overlay{position:absolute;inset:0;color:#111}.ticket-travel .artwork{filter:hue-rotate(20deg) saturate(.92)}.ticket-event .artwork{filter:hue-rotate(280deg) saturate(.86)}.ticket-title{position:absolute;left:4.5%;top:6.5%;width:51%;text-shadow:0 1px 2px #fff}.ticket-title .org{font-size:2.2mm;font-weight:700;text-transform:uppercase;letter-spacing:.25mm}.ticket-title h1{margin:.8mm 0;font-size:7.2mm;line-height:1.05}.ticket-title .dates{font-size:2.5mm;font-weight:700}.guest-block{position:absolute;left:30.5%;top:40%;width:34%;padding:2.5mm 3mm;background:#ffffffd9;border-radius:2mm;border-left:1.2mm solid <?=saas_h($accent)?>}.label,.info-grid span{font-size:1.8mm;letter-spacing:.2mm;color:#475467;font-weight:700}.guest{font-size:5mm;font-weight:800;line-height:1.05;margin-top:.8mm}.phone{font-size:2.4mm;margin-top:.8mm}.info-grid{position:absolute;left:30.5%;top:61%;width:43%;display:grid;grid-template-columns:1fr 1fr;gap:1.4mm}.info-grid>div{background:#ffffffdc;border-radius:1.4mm;padding:1.5mm 2mm;min-height:8.5mm}.info-grid span{display:block}.info-grid strong{display:block;font-size:2.8mm;margin-top:.6mm;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.due{color:#b42318}.ticket-no{position:absolute;left:30.5%;bottom:4.5%;font-size:1.9mm;font-weight:800;letter-spacing:.15mm;background:#fffdf0e6;padding:1.2mm 2mm;border-radius:1mm}.qr-frame{position:absolute;right:4.2%;top:38%;width:25mm;height:25mm;display:flex;align-items:center;justify-content:center;background:#fff;padding:1mm;border-radius:1mm}.qr-frame img{width:100%;height:100%;display:block}.two-up-sheet{width:210mm;height:168mm;margin:0 auto;page:two-up;display:flex;flex-direction:column}.two-up-sheet .ticket{width:210mm;height:84mm}.three-up-sheet{width:210mm;height:297mm;margin:0 auto;page:three-up;display:grid;grid-template-columns:190mm;grid-template-rows:repeat(3,92mm);row-gap:5mm;padding:7mm 10mm}.three-up-sheet .ticket{width:190mm;height:92mm}.cut-line{height:0;border-top:1px dashed #777;position:relative;flex:0 0 0}.cut-line:after{content:'CUT';position:absolute;left:50%;top:-2.5mm;transform:translateX(-50%);background:#fff;padding:0 2mm;font-size:1.8mm;color:#777}.two-up-sheet .ticket-title h1{font-size:5.1mm}.two-up-sheet .guest{font-size:3.5mm}.two-up-sheet .info-grid strong{font-size:2mm}.two-up-sheet .qr-frame{width:20mm;height:20mm}@media print{html,body{background:#fff}.controls{display:none}.sheet,.two-up-sheet{margin:0}.cut-line{display:block}}@media(max-width:1000px){.sheet,.ticket{width:100%;height:auto;aspect-ratio:2.5}.ticket-title h1{font-size:clamp(20px,4vw,34px)}.qr-frame{width:18%;height:auto;aspect-ratio:1}.two-up-sheet{width:100%;height:auto}.two-up-sheet .ticket{width:100%;height:auto;aspect-ratio:2.5}.two-up-sheet .cut-line{display:none}}
</style></head><body><div class="controls"><form method="post" style="display:inline-flex;gap:8px;align-items:center"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><label>Design <select name="template"><option value="classic" <?=($template==='classic'?'selected':'')?>>Classic</option><option value="travel" <?=($template==='travel'?'selected':'')?>>Travel</option><option value="event" <?=($template==='event'?'selected':'')?>>Event</option></select></label><button type="submit">Save design</button></form><?php $base=$adminMode?'ticket_id='.urlencode((string)$ticket['ticket_id']):'slug='.rawurlencode($slug).'&token='.rawurlencode($token); ?><a href="?<?=$base?>&template=<?=rawurlencode($template)?>&layout=1up"><button type="button">1 ticket / A4 landscape</button></a><a href="?<?=$base?>&template=<?=rawurlencode($template)?>&layout=2up"><button type="button" class="primary">2 tickets / A4 portrait</button></a><button type="button" class="primary" onclick="window.print()">Print</button><?php if($saveError):?><div class="ok"><?=saas_h($saveError)?></div><?php endif;?></div><?php if($printLayout==='3up'): ?><main class="three-up-sheet"><?php for($slot=0;$slot<3;$slot++): ?><?php ticket_card($ticketData,$template,$qrUrl,$accent,$customElements,$customDesign['background_image']??null); ?><?php endfor; ?></main><?php elseif($printLayout==='2up'): ?><main class="two-up-sheet"><?php ticket_card($ticketData,$template,$qrUrl,$accent,$customElements,$customDesign['background_image']??null); ?><div class="cut-line"></div><?php ticket_card($ticketData,$template,$qrUrl,$accent); ?></main><?php else: ?><main class="sheet"><?php ticket_card($ticketData,$template,$qrUrl,$accent); ?></main><?php endif; ?></body></html>